      "relay.asks.gate.not_paired_error": "\u06cc\u06c1 \u0641\u0648\u0646 \u0627\u0628\u06be\u06cc \u0627\u0633 \u0645\u0634\u06cc\u0646 \u0633\u06d2 \u062c\u0648\u0691\u0627 \u0646\u06c1\u06cc\u06ba \u06af\u06cc\u0627 \u2014 \u0627\u06cc\u06a9 \u0628\u0627\u0631 \u062c\u0648\u0691 \u062f\u06cc\u06ba \u062a\u0648 \u06cc\u06c1 \u0631\u0636\u0627\u0645\u0646\u062f\u06cc \u062e\u0648\u062f \u062f\u06d2 \u0633\u06a9\u06d2 \u06af\u0627\u06d4",
      "relay.asks.gate.notice_ask": "\u0627\u0633 \u0633\u06cc\u0634\u0646 \u0645\u06cc\u06ba \u0645\u0646\u0638\u0648\u0631\u06cc\u0627\u06ba ask \u067e\u0631 \u0628\u0631\u0642\u0631\u0627\u0631 \u06c1\u06cc\u06ba",
